#include <optional>
#include <set>

#include "rt/core.hpp"
#include "rt/harness.hpp"
#include "rt/text.hpp"
#include "support.hpp"
#include "todo/board.hpp"
#include "todo/model.hpp"
#include "todo/render.hpp"

namespace todo {

TEST(numbers_start_at_one) {
  board::World w;
  board::Lines out;
  CHECK_EQ(board::add(w, out, support::title("milk"), model::Priority::Normal, std::set<model::Tag>{}),
           model::TaskNo::proven(1));
  CHECK_EQ(board::add(w, out, support::title("bread"), model::Priority::Normal,
                      std::set<model::Tag>{support::tag("shop"), support::tag("home")}),
           model::TaskNo::proven(2));
  CHECK_EQ(rt::test::text(out), "added 1\nadded 2\n");
}

TEST(numbers_are_never_reused) {
  board::World w;
  board::Lines out;
  CHECK_EQ(board::add(w, out, support::title("a"), model::Priority::Normal, std::set<model::Tag>{}),
           model::TaskNo::proven(1));
  CHECK_EQ(board::add(w, out, support::title("b"), model::Priority::Normal, std::set<model::Tag>{}),
           model::TaskNo::proven(2));
  CHECK(board::remove(w, out, model::TaskNo::proven(2)).has_value());
  CHECK_EQ(board::add(w, out, support::title("c"), model::Priority::Normal, std::set<model::Tag>{}),
           model::TaskNo::proven(3));
}

TEST(empty_board_says_so) {
  board::World w;
  board::Lines out;
  board::list(w, out, false, std::nullopt);
  board::stats(w, out);
  CHECK_EQ(rt::test::text(out), "nothing to do\n0 open, 0 done\n");
}

TEST(list_ranks_urgent_first) {
  board::World w;
  board::Lines out;
  w = support::given_three_open_one_done();
  board::list(w, out, false, std::nullopt);
  CHECK_EQ(rt::test::text(out), "3 [ ] urgent !high #work\n2 [ ] plain\n1 [ ] low one !low\n");
}

TEST(list_all_and_by_tag) {
  board::World w;
  board::Lines out;
  w = support::given_three_open_one_done();
  board::list(w, out, true, std::optional<model::Tag>{support::tag("work")});
  CHECK_EQ(rt::test::text(out), "3 [ ] urgent !high #work\n4 [x] finished #home #work\n");
}

TEST(done_and_reopen_move_once) {
  board::World w;
  board::Lines out;
  w = support::given_three_open_one_done();
  CHECK(board::done(w, out, model::TaskNo::proven(2)).has_value());
  CHECK_EQ(rt::test::error_of(board::done(w, out, model::TaskNo::proven(2))),
           (std::optional{board::Refusal::AlreadyDone}));
  CHECK(board::reopen(w, out, model::TaskNo::proven(2)).has_value());
  CHECK_EQ(rt::test::error_of(board::reopen(w, out, model::TaskNo::proven(2))),
           (std::optional{board::Refusal::NotDone}));
  CHECK_EQ(rt::test::text(out), "2 [x] plain\n2 [ ] plain\n");
}

TEST(rename_keeps_the_rest) {
  board::World w;
  board::Lines out;
  w = support::given_three_open_one_done();
  CHECK(board::rename(w, out, model::TaskNo::proven(3), support::title("urgent, really")).has_value());
  CHECK_EQ(w.tasks.at(model::TaskNo::proven(3)),
           (model::Task{.no = model::TaskNo::proven(3),
                        .title = support::title("urgent, really"),
                        .status = model::Status::Open,
                        .priority = model::Priority::High,
                        .tags = std::set<model::Tag>{support::tag("work")}}));
}

TEST(clear_removes_only_done) {
  board::World w;
  board::Lines out;
  w = support::given_three_open_one_done();
  CHECK_EQ(board::clear(w, out), 1);
  board::stats(w, out);
  CHECK_EQ(rt::test::text(out), "cleared 1\n3 open, 0 done\n");
  CHECK(!w.tasks.contains(model::TaskNo::proven(4)));
}

TEST(unknown_numbers_are_refused) {
  rt::random::Prng prng = rt::random::Prng(24309);
  for (int run = 0; run < 200; ++run) {
    const auto no = support::gen_task_no(prng);
    board::World w;
    board::Lines out;
    w = support::given_three_open_one_done();
    [&]() {
      if (no.value() <= 4) {
        return;
      }
      CHECK_EQ(rt::test::error_of(board::done(w, out, no)), (std::optional{board::Refusal::NoTask}));
      CHECK_EQ(rt::test::error_of(board::reopen(w, out, no)), (std::optional{board::Refusal::NoTask}));
      CHECK_EQ(rt::test::error_of(board::rename(w, out, no, support::title("x"))),
               (std::optional{board::Refusal::NoTask}));
      CHECK_EQ(rt::test::error_of(board::remove(w, out, no)), (std::optional{board::Refusal::NoTask}));
      CHECK_EQ(rt::test::text(out), "");
    }();
  }
}

}  // namespace todo
